## 2️⃣ Domain Entities & Type Definitions (TypeScript)

```ts
// src/domain/entities/Order.ts
export type OrderId = number & { readonly __brand: unique symbol };

export enum OrderStatus {
  CREATED = 'CREATED',
  SAVED   = 'SAVED',
  READY   = 'READY',
  SERVED  = 'SERVED',
}

/**
 * Core business entity – immutable once constructed.
 */
export class Order {
  public readonly id: OrderId;
  public readonly orderTime: Date;   // when the order was placed
  public readonly prepTime: number;  // minutes required to prepare
  public readonly status: OrderStatus;

  private constructor(
    id: OrderId,
    orderTime: Date,
    prepTime: number,
    status: OrderStatus,
  ) {
    this.id = id;
    this.orderTime = orderTime;
    this.prepTime = prepTime;
    this.status = status;
  }

  /** Factory – validates invariants before creation */
  public static create(
    id: number,
    orderTime: Date,
    prepTime: number,
  ): Order {
    if (prepTime <= 0) {
      throw new ValidationError('prepTime must be > 0');
    }
    if (orderTime.getTime() < Date.now()) {
      // business rule: orders cannot be placed in the past
      throw new ValidationError('orderTime cannot be in the past');
    }
    return new Order(id as OrderId, orderTime, prepTime, OrderStatus.CREATED);
  }

  /** Transition to the next status – returns a new instance */
  public withStatus(status: OrderStatus): Order {
    return new Order(this.id, this.orderTime, this.prepTime, status);
  }

  /** Computed property – moment when the order becomes ready */
  public get readyAt(): Date {
    return new Date(this.orderTime.getTime() + this.prepTime * 60_000);
  }
}

// src/domain/value-objects/OrderReadyInfo.ts
export interface OrderReadyInfo {
  /** Order identifier */
  id: OrderId;
  /** Timestamp when the order is ready (orderTime + prepTime) */
  readyAt: Date;
}
```

